import Link from "next/link";
import Image from "next/image";
import { Button } from "@/components/ui/button";
import { RoomCard } from "./room-card";
import { cn } from "@/lib/utils";

interface Room {
  id: string;
  name: string;
  slug?: string;
  description: string;
  pricePerNight: number;
  capacity: number;
  bedCount: number;
  size: number | null;
  images: string[];
  featured: boolean;
}

interface FeaturedRoomsProps {
  rooms: Room[];
}

export function FeaturedRooms({ rooms }: FeaturedRoomsProps) {
  const featuredDestinations = [
    "Hà Nội",
    "TP. Hồ Chí Minh",
    "Đà Nẵng",
    "Nha Trang",
    "Đà Lạt",
    "Phú Quốc",
    "Hạ Long",
    "Hội An",
  ];

  // Reuse existing Unsplash sources already used in this repo to avoid adding new assets.
  const destinationImages = [
    "https://images.unsplash.com/photo-1571896349842-33c89424de2d?w=1200&h=800&fit=crop",
    "https://images.unsplash.com/photo-1566073771259-6a8506099945?w=1200&h=800&fit=crop",
    "https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=1200&h=800&fit=crop",
  ];

  return (
    <section className="py-16 bg-gray-50">
      <div className="container">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-4xl font-bold mb-4">Điểm đến nổi bật</h2>
          <p className="text-lg text-muted-foreground">Khám phá các địa điểm nổi tiếng ở Việt Nam</p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {featuredDestinations.map((name, index) => {
            const imageUrl = destinationImages[index % destinationImages.length];
            const isLarge = index === 0;

            return (
              <Link
                key={name}
                href="/rooms"
                className={cn(
                  "group block",
                  isLarge ? "sm:col-span-2 sm:row-span-2" : ""
                )}
              >
                <div
                  className={cn(
                    "relative overflow-hidden rounded-xl",
                    isLarge ? "aspect-[16/9] sm:aspect-auto sm:h-full" : "aspect-[16/9]"
                  )}
                >
                  <Image
                    src={imageUrl}
                    alt={name}
                    fill
                    sizes={isLarge ? "(min-width: 1024px) 66vw, 100vw" : "(min-width: 1024px) 33vw, 100vw"}
                    className="object-cover"
                  />
                  <div className="absolute inset-0 bg-black/40" />
                  <div className="absolute left-4 top-4">
                    <h3 className={cn("font-semibold text-white", isLarge ? "text-xl md:text-2xl" : "text-lg")}>{name}</h3>
                  </div>
                </div>
              </Link>
            );
          })}
        </div>

        {rooms.length > 0 && (
          <div className="mt-12">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {rooms.map((room) => (
                <RoomCard
                  key={room.id}
                  room={{
                    ...room,
                    slug: room.slug || "",
                  }}
                />
              ))}
            </div>
          </div>
        )}

        <div className="text-center mt-12">
          <Button asChild size="lg" variant="outline">
            <Link href="/rooms">View All Rooms</Link>
          </Button>
        </div>
      </div>
    </section>
  );
}
